import{_ as a,o,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"例程：定时与事件触发","description":"把重复的工作交给例程，按时间表或在收到消息、代码通知等事件时自动运行。","frontmatter":{"related":["/automation/skills","/automation/daily-briefing","/basics/safety-approvals"],"title":"例程：定时与事件触发","description":"把重复的工作交给例程，按时间表或在收到消息、代码通知等事件时自动运行。","section":"automation","order":1,"tags":["自动化","例程","定时任务","触发器"],"sources":["https://docs.x.ai/grok-bot/skills-routines-and-automations","https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/approvals-security-and-privacy"],"wordCount":844,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"例程：定时与事件触发 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"把重复的工作交给例程，按时间表或在收到消息、代码通知等事件时自动运行。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/automation/routines"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/automation-routines-4a272aedee.png"}],["meta",{"property":"og:image:alt","content":"例程：定时与事件触发 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"例程：定时与事件触发 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"把重复的工作交给例程，按时间表或在收到消息、代码通知等事件时自动运行。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/automation-routines-4a272aedee.png"}],["meta",{"name":"twitter:image:alt","content":"例程：定时与事件触发 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/automation/routines"}]]},"headers":[],"relativePath":"automation/routines.md","filePath":"automation/routines.md","lastUpdated":1792514041000}'),s={name:"automation/routines.md"};function i(r,t,l,p,c,u){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="例程-定时与事件触发" tabindex="-1">例程：定时与事件触发 <a class="header-anchor" href="#例程-定时与事件触发" aria-label="Permalink to &quot;例程：定时与事件触发&quot;">​</a></h1><p><strong>例程</strong>就是告诉某个 Bot：&quot;什么时候，自动做这件事&quot;。它在云端运行，你关了电脑、出差、睡觉，它都照常执行，做完把结果发到对话里。</p><h2 id="两种触发方式" tabindex="-1">两种触发方式 <a class="header-anchor" href="#两种触发方式" aria-label="Permalink to &quot;两种触发方式&quot;">​</a></h2><ul><li><strong>定时</strong>：每天 8 点、每周一上午、每月 1 号……背后是类似 cron 的时间表。</li><li><strong>事件</strong>：在支持的情况下，由外部事件触发，比如 Slack 某个频道出现特定消息、GitHub 有新通知、收到 Webhook 请求等。支持哪些事件源以官方最新说明为准。</li></ul><h2 id="先手动跑顺-再自动化" tabindex="-1">先手动跑顺，再自动化 <a class="header-anchor" href="#先手动跑顺-再自动化" aria-label="Permalink to &quot;先手动跑顺，再自动化&quot;">​</a></h2><p>官方推荐的顺序很朴素：<strong>一次性任务 → 跑稳定 → 存成技能 → 再设例程</strong>。一个你还没手动验证过的流程，自动化以后只会更快地出错。</p><h2 id="怎么创建" tabindex="-1">怎么创建 <a class="header-anchor" href="#怎么创建" aria-label="Permalink to &quot;怎么创建&quot;">​</a></h2><p>直接在对话里跟&quot;负责这件事的 Bot&quot;说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 8:00（按你所在的时区），运行&quot;每日行业动态&quot;技能：</span></span>
<span class="line"><span>- 来源：我关注的 10 个官网更新页和 X 账号（见技能里的清单）；</span></span>
<span class="line"><span>- 结果：一份 10 条以内的要点清单，每条附原文链接，发在这个对话里；</span></span>
<span class="line"><span>- 边界：不要发帖、不要联系任何人；</span></span>
<span class="line"><span>- 异常：如果某个来源打不开，在结果末尾列出来，不要用旧内容凑数。</span></span></code></pre></div><p>创建前确认六件事：<strong>由哪个 Bot 负责、时间和时区、数据来源、期望结果、审批边界、来源缺失时怎么办</strong>。创建好后，Bot 会告诉你下次运行时间。</p><h2 id="事件触发要-窄" tabindex="-1">事件触发要&quot;窄&quot; <a class="header-anchor" href="#事件触发要-窄" aria-label="Permalink to &quot;事件触发要&quot;窄&quot;&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当 Slack 的 #客户反馈 频道里出现包含&quot;无法登录&quot;的消息时，</span></span>
<span class="line"><span>整理该用户的问题描述和截图，汇总成一条工单草稿发给我。不要在 Slack 里回复。</span></span></code></pre></div><p>不要设&quot;每条新消息都处理&quot;这种宽泛的监听，既浪费用量，又容易对无关内容采取行动。</p><h2 id="测试和管理" tabindex="-1">测试和管理 <a class="header-anchor" href="#测试和管理" aria-label="Permalink to &quot;测试和管理&quot;">​</a></h2><ul><li><strong>测试运行</strong>：创建或修改后先测一次，检查是否用了最新数据、格式对不对、有没有在该停的地方停下、出错时有没有明说。</li><li><strong>管理</strong>：点 Bot 名称打开详情，在例程列表里可以查看说明和时间表，暂停、恢复、测试、编辑或删除。</li><li><strong>限制</strong>：一个 Bot 能拥有的例程数量、两次运行的最短间隔都有上限，以官方最新说明为准。</li></ul><div class="warning custom-block"><p class="custom-block-title">测试运行是真的在执行</p><p>测试不是演习，它会真的打开网站、修改文件、调用连接器。用安全的输入测试，写操作一定放在审批后面。另外，删除例程立即生效且无法撤销。</p></div><div class="tip custom-block"><p class="custom-block-title">长时间不用会被询问</p><p>为了避免无人看管时消耗用量，长时间不活跃后，应用可能询问你是否继续运行例程，没有回应可能会被暂停。回来后记得检查一下。</p></div><h2 id="设计可靠例程的小原则" tabindex="-1">设计可靠例程的小原则 <a class="header-anchor" href="#设计可靠例程的小原则" aria-label="Permalink to &quot;设计可靠例程的小原则&quot;">​</a></h2><ul><li>自动化&quot;准备工作&quot;，而不是&quot;最终执行&quot;：先起草、核对、建议。</li><li>写明&quot;没数据 / 数据过期&quot;时怎么办。</li><li>来源网站或格式变了，及时暂停并重新测试。</li><li><strong>第一步做便宜的检查</strong>：先看&quot;有没有新内容&quot;，没有就一句话结束，不进入调研、写稿、出图。平淡的日子里，大部分运行到这一步就停了，最省用量。</li></ul><h2 id="用-webhook-例程等长任务跑完" tabindex="-1">用 Webhook 例程等长任务跑完 <a class="header-anchor" href="#用-webhook-例程等长任务跑完" aria-label="Permalink to &quot;用 Webhook 例程等长任务跑完&quot;">​</a></h2><p>Webhook 触发的例程有个很实用的用法：<strong>当&quot;闹钟&quot;</strong>。Bot 把长任务（Codex CLI、Claude Code、构建、抓取）交出去以后不用反复去看，任务结束时向一个 Webhook 例程发通知，由它把派活的 Bot 叫醒接着验收。</p><p>每个 Bot 的 Webhook 地址是各自独立的，开源技能 <a href="/daily/2026-10-21-wake-on-done">Wake on Done</a> 的做法是只给一个转发 Bot 配 Webhook，再按 Bot ID 转发，配一次所有 Bot 都能用。省用量的整体思路见<a href="/daily/2026-10-21-bot-as-foreman">让 Bot 当工头：三层分工法</a>。</p>`,22)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
